  "it.formd_ITR-1": "For a resident individual with salary or pension, up to two house properties and other sources such as interest, and total income up to ₹50 lakh.",
  "it.formd_ITR-2": "For an individual or HUF with no business or profession income who has capital gains, income above ₹50 lakh, more than two house properties, foreign assets or income, or does not fit ITR-1.",
  "it.formd_ITR-3": "For an individual or HUF with business or profession income that is not under a presumptive scheme, a partner in a firm, or anyone who does not fit ITR-4.",
