  "it.basis": "ई आँकड़ा कथी पर आधारित अछि ({d} धरि)",
  "it.b1": "रेट ({d} धरि), टैक्स साल 2026-27: नव रिजीम ₹4 लाख धरि शून्य, ₹8 लाख धरि 5%, ₹12 लाख धरि 10%, ₹16 लाख धरि 15%, ₹20 लाख धरि 20%, ₹24 लाख धरि 25%, ओहि सँ ऊपर 30%; रिबेट एहन जे ₹12 लाख धरिक आमदनी पर टैक्स नहि, ओहि सँ ठीक ऊपर मार्जिनल रिलीफ़; सैलरी पर स्टैंडर्ड डिडक्शन ₹75,000। पुरान रिजीम: ₹2.5 लाख धरि शून्य (60 पर ₹3 लाख, 80 पर ₹5 लाख), ₹5 लाख धरि 5%, ₹10 लाख धरि 20%, ओहि सँ ऊपर 30%; ₹5 लाख धरि ₹12,500 रिबेट; स्टैंडर्ड डिडक्शन ₹50,000। ई ओही रेट अछि जे सैलरी स्लिप टूल पहिने सँ इस्तेमाल करैत अछि; एहि बिल्ड मे Finance Act सँ फेर नहि पढ़ल गेल, तेँ जाँचू।",
  "it.b2": "एडवांस टैक्स (Income-tax Act 2025, sections 403 सँ 408): जखन TDS क बाद टैक्स ₹10,000 वा बेसी हो तखन लगैत अछि; 15 जून धरि 15%, 15 सितंबर धरि 45%, 15 दिसंबर धरि 75%, 15 मार्च धरि सभ; प्रिज़म्पटिव टैक्सपेयर सभ 15 मार्च धरि भरैत छथि; 31 मार्च धरिक पेमेंट ओही साल मे गनल जाइत अछि; 60 वा बेसी उमरक निवासी जिनकर बिज़नेस आमदनी नहि अछि, छूट मे छथि।",
  "it.b3": "ब्याज: section 424 (पुरान 234B) कमी पर हर महीना वा महीनाक हिस्सा पर 1% अछि जखन टैक्सक 90% सँ कम भरल गेल; section 425 (पुरान 234C) पहिल तीन किस्तक कमी पर 3% अछि (जँ 15 जून धरि 12% आ 15 सितंबर धरि 36% भरल तँ नहि) आ मार्चक कमी पर 1%।",
  "it.b4": "ऊपरक सेक्शन 15 Nov 2026 केँ Income Tax Department क वेबसाइट (incometaxindia.gov.in) पर आधिकारिक टेक्स्ट सँ शब्द-शब्द जाँचल गेल। छापल Act मान्य अछि।",
  "it.b5": "बुक प्रॉफिट टैक्स बला प्रॉफिट नहि अछि: Act क अंतर्गत डेप्रिसिएशन, नहि मानल गेल खर्च आ प्रिज़म्पटिव नियम एकरा बदलैत अछि। ई प्लान आ डेटा शीट अपन अकाउंटेंट केँ दिअ।",
  "it.b6": "निकालल नहि गेल: सरचार्ज, खास रेट बला कैपिटल गेन, विदेशी टैक्स रिलीफ़, नाबालिगक आमदनी पर टैक्स, आ देरी सँ फ़ाइल करबा पर ब्याज।",
  "it.b7": "किछु फ़ाइल नहि होइत अछि आ अहाँक बुक्स मे किछु दर्ज नहि होइत अछि।",
  "it.itr_h": "किछु प्रश्नक उत्तर दिअ आ देखू कोन रिटर्न फ़ॉर्म ठीक अछि, किएक, आ कोन कागज तैयार राखू।",
