  "it.formd_ITR-2": "बिना बिज़नेस वा प्रोफ़ेशनक आमदनी बला व्यक्ति वा HUF लेल जिनका कैपिटल गेन, ₹50 लाख सँ ऊपर आमदनी, दू सँ बेसी मकान, विदेशी संपत्ति वा आमदनी अछि, वा जे ITR-1 मे नहि अबैत छथि।",
  "it.formd_ITR-3": "प्रिज़म्पटिव स्कीम सँ बाहर बिज़नेस वा प्रोफ़ेशनक आमदनी बला व्यक्ति वा HUF, फ़र्मक पार्टनर, वा जे ITR-4 मे नहि अबैत छथि हुनका लेल।",
  "it.formd_ITR-4": "प्रिज़म्पटिव बिज़नेस आमदनी, ₹50 लाख धरि कुल आमदनी, सैलरी वा पेंशन, दू मकान धरि आ आन स्रोत बला निवासी व्यक्ति वा HUF लेल।",
  "it.formd_ITR-5": "फ़र्म, LLP, व्यक्तिक संघ (AOP) आ व्यक्तिक समूह (BOI) लेल।",
  "it.formd_ITR-6": "धार्मिक वा परोपकारी काज लेल छूट माँगए बला कंपनी छोड़ि आन कंपनी लेल।",
  "it.formd_ITR-7": "ट्रस्ट, संस्था, राजनीतिक पार्टी आ एहने लोक लेल।",
  "it.w_company": "कंपनी ITR-6 भरैत अछि।",
  "it.w_firm": "फ़र्म, LLP वा संघ ITR-5 भरैत अछि।",
  "it.w_other": "ट्रस्ट, संस्था आ राजनीतिक पार्टी ITR-7 भरैत अछि।",
  "it.w_partner": "जाहि फ़र्म मे अहाँ पार्टनर छी ओहि सँ भेटल पारिश्रमिक वा ब्याज बिज़नेस आमदनी अछि, ITR-3 मे देखाओल जाइत अछि।",
  "it.w_business": "अहाँ बुक्स सँ बिज़नेस वा प्रोफ़ेशनल प्रॉफिट निकालैत छी, जाहि लेल ITR-3 चाही।",
  "it.w_presnot": "प्रिज़म्पटिव फ़ॉर्म व्यक्ति आ HUF लेल अछि।",
  "it.w_nonres": "जे निवासी नहि छथि ओ ITR-1 वा ITR-4 इस्तेमाल नहि क’ सकैत छथि।",
  "it.w_over50": "₹50 लाख सँ ऊपर कुल आमदनी पर ITR-1 आ ITR-4 नहि चलत।",
  "it.w_capgain": "लिस्टेड शेयरक छोट सीमा सँ अलग कैपिटल गेन लेल ITR-2 वा ITR-3 चाही।",
  "it.w_houses": "दू सँ बेसी मकान पर ITR-1 आ ITR-4 नहि चलत।",
  "it.w_foreign": "विदेशी संपत्ति वा विदेशी आमदनी लेल ITR-2 वा ITR-3 चाही।",
  "it.w_director": "कंपनीक डायरेक्टर ITR-1 वा ITR-4 इस्तेमाल नहि क’ सकैत छथि।",
  "it.w_unlisted": "अनलिस्टेड शेयर रहला पर ITR-1 आ ITR-4 नहि चलत।",
  "it.w_agri": "₹5,000 सँ ऊपर खेतीक आमदनी पर ITR-1 आ ITR-4 नहि चलत।",
  "it.w_loss": "आगाँ ल’ जएबाक वा सेट ऑफ करबाक घाटा लेल ITR-2 वा ITR-3 चाही।",
  "it.w_esop": "नियोक्ताक शेयर पर टालल टैक्स लेल ITR-2 वा ITR-3 चाही।",
  "it.w_crypto": "वर्चुअल डिजिटल एसेट सँ आमदनी लेल ITR-2 वा ITR-3 चाही।",
  "it.w_huf": "ITR-1 केवल व्यक्ति लेल अछि; बिना बिज़नेस आमदनी बला HUF ITR-2 भरैत अछि।",
  "it.w_pres2": "अहाँक आन उत्तर सँ ITR-4 नहि चलत, तेँ बिज़नेस आमदनी ITR-3 मे जाइत अछि।",
  "it.w_pres": "प्रिज़म्पटिव बिज़नेस आमदनी आ साधारण आन आमदनी लेल ITR-4 ठीक अछि।",
  "it.w_simple": "केवल सैलरी, मकान आ ब्याज, सीमाक भीतर, लेल ITR-1 ठीक अछि।",
  "it.n_forms": "शर्त 31 मार्च 2026 केँ समाप्त सालक लेल नोटिफ़ाई कएल रिटर्न पर आधारित अछि (टैक्स पोर्टलक अनुसार, ITR-1 आ ITR-4 मे आब दू मकान धरि चलैत अछि)। टैक्स साल 2026-27 क रिटर्न Income-tax Rules, 2026 क अंतर्गत एखन नोटिफ़ाई होएबाक अछि: फ़ाइल करबा सँ पहिने फ़ॉर्मक अपन लिस्ट पढ़ू जे के एकरा इस्तेमाल नहि क’ सकैत छथि।",
  "it.n_ltcg": "लिस्टेड शेयर वा इक्विटी फंड पर छोट लॉन्ग-टर्म गेन किछु साल ITR-1 आ ITR-4 मे मान्य छल; 2026-27 लेल ई पक्का नहि अछि, तेँ ITR-2 सुरक्षित विकल्प अछि आ फ़ॉर्मक अपन लिस्ट मान्य अछि।",
  "it.n_ae": "Section 44AE (माल ढोबए बला गाड़ी) क अपन शर्त अछि; प्रिज़म्पटिव फ़ॉर्म इस्तेमाल करबा सँ पहिने जाँचू।",
