  "ca.intro": "एकटा बिज़नेस आ अवधि केँ एकटा केवल पढ़बा बला फ़ाइल (.nsca) मे पैक करैत अछि। ई अपन अकाउंटेंट केँ WhatsApp वा ईमेल सँ पठाउ। ओ ca.niveshsahayak.in पर खोलि क’ बुक्स पढ़ैत छथि, प्रश्न जोड़ैत छथि आ अहाँ केँ कमेंट वापस पठबैत छथि।",
  "ca.notlive": "ई फ़ाइल सौंपब अछि, चालू साझा लॉगिन नहि। अहाँक अकाउंटेंट बुक्स ओहिना देखैत छथि जेना फ़ाइल बनबैत काल छल। चालू लॉगिन लेल एहन सर्वर चाही जे अहाँक बुक्स राखए, आ Nivesh Sahayak लग कोनो सर्वर नहि अछि: अहाँक बुक्स अहाँक डिवाइस पर रहैत अछि। नव एंट्री लेल नव फ़ाइल बनाउ।",
  "ca.what": "एहि मे की जाइत अछि",
  "ca.earlier": "पहिल तारीख सँ पहिनुक एंट्री सेहो (ओपनिंग बैलेंस आ एजिंग लेल ज़रूरी)",
  "ca.items": "खरीद आ बिक्री रेटक संग आइटम लिस्ट (स्टॉक लेल ज़रूरी)",
  "ca.extra": "केवल जँ अहाँ टिक करी",
  "ca.extrah": "टिक केने बिना छोड़ल जाइत अछि। फोटो (लोगो, दस्तखत), अहाँक PIN आ बैकअप सेटिंग कहियो शामिल नहि होइत अछि।",
