  "ca.cIntro": "अहाँक अकाउंटेंट प्रश्न आ कमेंटक एकटा छोट फ़ाइल (.nsca-comments) वापस पठबैत छथि। एतय लोड करू आ हर प्रश्न ओहि एंट्रीक बगल मे देखू जाहि बारे मे अछि। जवाब दिअ, बंद मार्क करू, आ फ़ाइल फेर सेव क’ वापस पठाउ।",
