  "ca.general": "सामान्य कमेंट",
  "cv.h1": "अकाउंटेंट व्यूअर: क्लाइंटक पठाओल बुक्स फ़ाइल खोलू",
  "cv.intro": "अहाँक क्लाइंट एक अवधिक अपन बुक्स एकटा फ़ाइल मे पैक क’ WhatsApp वा ईमेल सँ पठबैत छथि। एतय खोलि क’ पढ़ू: बकाया, पार्टी, लेजर, डे बुक, GST हिसाब, फाइनल अकाउंट्स आ हर डॉक्यूमेंट। खोजू आ फ़िल्टर करू, कोनो एंट्री पर प्रश्न पूछू, आ अपन कमेंट छोट फ़ाइल रूप मे वापस पठाउ। मुफ़्त, बिना लॉगिन, आ किछु अपलोड नहि होइत अछि: फ़ाइल अहाँक ब्राउज़रक भीतर पढ़ल जाइत अछि।",
  "cv.drop": ".nsca फ़ाइल एतय छोड़ू",
  "cv.choose": "फ़ाइल चुनू",
  "cv.dropnote": "फ़ाइल एही डिवाइस पर रहैत अछि। एतय किछु सेव नहि होइत अछि आ एतय सँ अहाँ क्लाइंटक बुक्स नहि बदलि सकैत छी।",
  "cv.nav.home": "सारांश",
  "cv.docs": "डॉक्यूमेंट",
  "cv.day": "डे बुक",
  "cv.fin": "फाइनल अकाउंट्स",
  "cv.gst": "GST हिसाब",
  "cv.cT": "प्रश्न आ कमेंट",
  "cv.how.h": "ई कोना काज करैत अछि",
  "cv.how.1": "अहाँक क्लाइंट Nivesh Sahayak खोलैत छथि, हमर डेटा मे जाइत छथि, अकाउंटेंट केँ पठाउ, आ एक बिज़नेस आ अवधि लेल \"हमर अकाउंटेंट लेल फ़ाइल बनाउ\" चुनैत छथि।",
  "cv.how.2": "ओ अहाँ केँ फ़ाइल (.nsca सँ अंत होइत) आ एकहि मैसेज मे एकटा छोट चेक कोड पठबैत छथि।",
  "cv.how.3": "अहाँ एहि पेज पर फ़ाइल खोलैत छी। पेज बतबैत अछि जे फ़ाइल बिना बदलाव अछि कि नहि आ अहाँ केँ क्लाइंटक देल चेक कोड लिखि क’ मिलाबए दैत अछि।",
  "cv.how.4": "बुक्स पढ़ू, खोजू, आ कोनो डॉक्यूमेंट, डे बुक एंट्री वा स्क्रीन पर \"प्रश्न वा कमेंट जोड़ू\" दबाउ। अहाँ जे लिखैत छी से सभ एही ब्राउज़र मे रहैत अछि।",
  "cv.how.5": "जखन काज भ’ जाए, \"प्रश्न आ कमेंट\" खोलू आ छोट .nsca-comments फ़ाइल वापस पठाउ। अहाँक क्लाइंट ओकरा लोड क’ हर प्रश्न एंट्रीक बगल मे देखैत छथि। ओ जवाब द’ सकैत छथि, आ अहाँ जवाब एतय लोड क’ सकैत छी।",
  "cv.live.h": "फ़ाइल सौंपब, चालू लॉगिन नहि",
  "cv.live.p": "ई फ़ाइल सौंपब अछि। अहाँ क्लाइंटक खाता मे लॉगिन नहि करैत छी आ बाद मे कएल बदलाव नहि देखैत छी। चालू साझा लॉगिन लेल बुक्स राखए बला सर्वर चाही, आ Nivesh Sahayak लग कोनो सर्वर नहि अछि: बुक्स क्लाइंटक डिवाइस पर रहैत अछि। नव अवधि वा सुधारक बाद क्लाइंट सँ नव फ़ाइल माँगू।",
  "cv.safe.h": "फ़ाइल मे की अछि, आ की नहि",
  "cv.safe.p": "अहाँक क्लाइंट टिक करैत छथि जे की जाएत। सामान्यतः फ़ाइल मे एक बिज़नेसक अवधिक अंत धरिक एंट्री, पार्टी आ आइटम रहैत अछि। कोटेशन आ ऑर्डर, सैलरी आ स्टाफक रिकॉर्ड, फ़ोन नंबर आ ई-मेल पता, आ बिज़नेसक बैंक खाताक जानकारी छोड़ल जाइत अछि जाबत क्लाइंट टिक नहि करथि। फोटो, PIN आ बैकअप सेटिंग कहियो शामिल नहि होइत अछि। फ़ाइल मे चेकसम रहैत अछि जाहि सँ कोनो बदलाव एहि पेज पर देखाइत अछि। चेकसम ओहि आदमी केँ नहि रोकि सकैत अछि जे फ़ाइल बदलि क’ चेकसम फेर निकालए, तेँ चेक कोड ओहि कोड सँ मिलाउ जे क्लाइंट अलग सँ पठौलनि।",
  "cv.readonly": "ई फ़ाइलक केवल पढ़बा बला व्यू अछि: एतय किछु बदलल वा सेव नहि कएल जा सकैत अछि।",
  "cv.notfile": "ई Nivesh Sahayak अकाउंटेंट फ़ाइल (.nsca) नहि अछि।",
  "cv.iscomments": "ई कमेंट फ़ाइल अछि। पहिने बुक्स फ़ाइल (.nsca) खोलू, फेर \"प्रश्न आ कमेंट\" सँ कमेंट लोड करू।",
